   10  export type AuthState = 'authenticated' | 'unauthenticated' | 'unavailable' | 'loading';
   11  
   12  /**
   13   * UserService - Manages authentication state for the current user.
   14   *
   15   * ## Endpoints
   16   *
   17   * This service uses GET /user (not /users/:id or /profiles/:username):
   18   * - GET /user → Returns the authenticated user's own data (JWT token identifies who you are)
   19   * - GET /profiles/:username → Different endpoint for viewing any user's public profile (see ProfileService)
   20   *
   21   * ## Auth States
   22   *
   23   * - 'loading': Initial state, checking if stored token is valid
   24   * - 'authenticated': Token valid, user data loaded
   25   * - 'unauthenticated': No token or token invalid (4XX error)
   26   * - 'unavailable': Server error (5XX), token kept for retry
   27   *
   28   * ## Error Handling on GET /user
   29   *
   30   * - 4XX errors (400, 401, 403, 404): Token is invalid → logout, clear token
   31   * - 5XX errors (500, 503) or network errors: Server is down → keep token, auto-retry
   32   *
   33   * The distinction matters: a 401 means "your token is bad" (clear it), while a 500
   34   * means "server is broken" (keep the token, it might work when server recovers).
   35   *
   36   * ## Auto-Retry
   37   *
   38   * When in 'unavailable' state, the service automatically retries with exponential
   39   * backoff: 2s → 4s → 8s → 16s → 16s → ... (capped at 16s, retries indefinitely).
   40   * The UI shows "Connecting..." while retrying. User can also just reload the page.
   41   *
   42   * ## Global 401 Handling
   43   *
   44   * For other endpoints (not /user), 401 errors are caught by errorInterceptor
   45   * which calls purgeAuth() - this handles "token expired mid-session" scenarios.
   46   */
   47  @Injectable({ providedIn: 'root' })
   48  export class UserService {
   49    private currentUserSubject = new BehaviorSubject<User | null>(null);
   50    public currentUser = this.currentUserSubject.asObservable().pipe(distinctUntilChanged());
   51  
   52    private authStateSubject = new BehaviorSubject<AuthState>('loading');
   53    public authState = this.authStateSubject.asObservable().pipe(distinctUntilChanged());
   54  
   55    public isAuthenticated = this.currentUser.pipe(map(user => !!user));
   56  
   57    /**
   58     * Synchronously get the current cached user value.
   59     * Returns null if not authenticated or still loading.
   60     */
   61    getCurrentUserSync(): User | null {
   62      return this.currentUserSubject.getValue();
   63    }
   64  
   65    private retryAttempt = 0;
   66    private retrySubscription: Subscription | null = null;
   67  
   68    constructor(
   69      private readonly http: HttpClient,
   70      private readonly jwtService: JwtService,
   71      private readonly router: Router,
   72    ) {}
   73  
   74    login(credentials: { email: string; password: string }): Observable<{ user: User }> {
   75      return this.http
   76        .post<{ user: User }>('/users/login', { user: credentials })
   77        .pipe(tap(({ user }) => this.setAuth(user)));
   78    }
   79  
   80    register(credentials: { username: string; email: string; password: string }): Observable<{ user: User }> {
   81      return this.http.post<{ user: User }>('/users', { user: credentials }).pipe(tap(({ user }) => this.setAuth(user)));
   82    }
   83  
   84    logout(): void {
   85      this.purgeAuth();
   86      void this.router.navigate(['/']);
   87    }
   88  
   89    getCurrentUser(): Observable<{ user: User }> {
   90      return this.http.get<{ user: User }>('/user').pipe(
   91        tap({
   92          next: ({ user }) => this.setAuth(user),
   93          error: (err: HttpErrorResponse) => this.handleAuthError(err),
   94        }),
   95        shareReplay(1),
   96        catchError(() => EMPTY),
   97      );
   98    }
   99  
  100    /**
  101     * Handle errors from /api/user endpoint
  102     * - 4XX errors: Token is invalid, logout the user
  103     * - 5XX/network errors: Server issue, enter "unavailable" mode (keep token, show placeholder)
  104     */
  105    private handleAuthError(err: HttpErrorResponse): void {
  106      const status = err.status;
  107  
  108      if (status >= 400 && status < 500) {
  109        // 4XX: Client error (invalid token, forbidden, etc.) - logout
  110        this.purgeAuth();
  111      } else {
  112        // 5XX or network error (status 0) - auth temporarily unavailable
  113        this.setAuthUnavailable();
  114      }
  115    }
  116  
  117    /**
  118     * Set auth state to unavailable (server error, but keep token for retry)
  119     */
  120    private setAuthUnavailable(): void {
  121      this.currentUserSubject.next(null);
  122      this.authStateSubject.next('unavailable');
  123      this.scheduleRetry();
  124    }
  125  
  126    /**
  127     * Schedule auto-retry with exponential backoff: 2s, 4s, 8s, 16s, 16s, 16s...
  128     */
  129    private scheduleRetry(): void {
  130      this.cancelRetry();
  131  
  132      if (!this.jwtService.getToken()) {
  133        return; // No token, nothing to retry
  134      }
  135  
  136      // Calculate delay: 2, 4, 8, 16, 16, 16... (capped at 16s)
  137      const delaySeconds = Math.min(2 * Math.pow(2, this.retryAttempt), 16);
  138      this.retryAttempt++;
  139  
  140      this.retrySubscription = timer(delaySeconds * 1000).subscribe(() => {
  141        if (this.jwtService.getToken()) {
  142          this.authStateSubject.next('loading');
  143          this.getCurrentUser().subscribe();
  144        }
  145      });
  146    }
  147  
  148    /**
  149     * Cancel any pending retry
  150     */
  151    private cancelRetry(): void {
  152      if (this.retrySubscription) {
  153        this.retrySubscription.unsubscribe();
  154        this.retrySubscription = null;
  155      }
  156    }
